"""Synthetic orders with structures seen in real unit orders (invented names) — for the excerpt assembly audit."""
import sys,os
from docx import Document
from docx.shared import Pt
OUT=(sys.argv[1] if len(sys.argv)>1 else 'stress').rstrip('/')+'/';os.makedirs(OUT,exist_ok=True)
HEAD=lambda n,dd,mm:['ПРИКАЗ','КОМАНДИРА ВОЙСКОВОЙ ЧАСТИ 55555','по строевой части',f'« {dd} » {mm} 2026 г. № {n}','г. Энск','']
SIGN=['','КОМАНДИР ВОЙСКОВОЙ ЧАСТИ 55555','полковник\tА.Энский','','ВРИО НАЧАЛЬНИКА ШТАБА ВОЙСКОВОЙ ЧАСТИ 55555','майор','Б.Штабов']
def doc(lines,name,table=None,numbered=None):
  d=Document()
  for t in lines:
    if t=='<TABLE>':
      tb=d.add_table(rows=1,cols=4);h=tb.rows[0].cells
      for i,x in enumerate(table[0]):h[i].text=x
      for r in table[1:]:
        c=tb.add_row().cells
        for i,x in enumerate(r):c[i].text=x
      continue
    if isinstance(t,tuple) and t[0]=='NUM':d.add_paragraph(t[1],style='List Number');continue
    d.add_paragraph(t)
  d.save(OUT+name)
